/* Fire Drill tile renderer (S-FIRE-DRILL-DASHBOARD-TILE-001, 2026-08-12)
 *
 * Fetches js/fire-drill-tile-data.json (same-origin, same repo) and
 * populates the #hal-section "Fire Drill — Sovereignty Practice" card.
 * That JSON is generated by
 * hal-stack/architecture/fire-drill-reports/build-tile-data.py in the
 * two-birds-portfolio repo, derived from the report archive at run time —
 * NO FAKE TIMESTAMPS: nothing here is hand-typed. If this script cannot
 * load the data file, it says so plainly rather than showing stale or
 * invented values.
 */
(function () {
  function setBadge(id, text, cls) {
    var el = document.getElementById(id);
    if (!el) return;
    el.textContent = text;
    el.className = 'hal-badge ' + cls;
  }

  function fmtQuarterlyFloor(qf) {
    var gh = qf.github, an = qf.anthropic;
    var parts = [];
    parts.push('GitHub ' + (gh.met ? 'met' : 'MISSED') + ' (' + gh.last_drill_date + ')');
    parts.push('Anthropic ' + (an.met ? 'met' : 'MISSED') + ' (' + an.last_drill_date + ')');
    var ok = gh.met && an.met;
    return { text: parts.join(' · '), ok: ok };
  }

  function render(data) {
    setBadge(
      'fd-last-drill',
      data.last_drill.date + ' — ' + data.last_drill.service,
      data.last_drill.date === 'none' ? 'pending' : 'ok'
    );

    var verdict = data.last_drill.verdict;
    setBadge('fd-last-verdict', verdict, verdict === 'PASSED' ? 'ok' : 'pending');

    setBadge(
      'fd-never-drilled',
      data.never_drilled_count === 0 ? '0 — all drilled' : data.never_drilled_count + ' (' + data.never_drilled.join(', ') + ')',
      data.never_drilled_count === 0 ? 'ok' : 'pending'
    );

    var qf = fmtQuarterlyFloor(data.quarterly_floor);
    setBadge('fd-quarterly-floor', qf.text, qf.ok ? 'ok' : 'pending');

    setBadge(
      'fd-open-followups',
      String(data.open_followups_total),
      data.open_followups_total === 0 ? 'ok' : 'pending'
    );

    var genEl = document.getElementById('fd-generated-at');
    if (genEl) {
      genEl.textContent = data.generated_at + ' (' + data.reports_read + ' report' + (data.reports_read === 1 ? '' : 's') + ' read)';
    }
  }

  function renderError(msg) {
    ['fd-last-drill', 'fd-last-verdict', 'fd-never-drilled', 'fd-quarterly-floor', 'fd-open-followups'].forEach(function (id) {
      setBadge(id, 'data unavailable', 'offline');
    });
    var genEl = document.getElementById('fd-generated-at');
    if (genEl) genEl.textContent = 'unavailable — ' + msg;
  }

  document.addEventListener('DOMContentLoaded', function () {
    fetch('js/fire-drill-tile-data.json', { cache: 'no-store' })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(render)
      .catch(function (err) {
        renderError(err.message || 'fetch failed');
      });
  });
})();
